-- No clinical changes persist; synthetic identifiers only.
DO $$ DECLARE blocked boolean; BEGIN
 blocked:=false; BEGIN UPDATE public.medicamentos SET estoque_quantidade=99 WHERE id='30000000-0000-4000-8000-000000000002'; EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE '%MACRO02_COMPATIBLE_WRITER_REQUIRED%' THEN RAISE; END IF; blocked:=true; END; IF NOT blocked THEN RAISE EXCEPTION 'TEST_POSTGRES_NOJWT_ACTIVE'; END IF;
 blocked:=false; BEGIN DELETE FROM public.persons WHERE id='10000000-0000-4000-8000-000000000002'; EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE '%MACRO02_PROTECTED_PERSON_HISTORY%' THEN RAISE; END IF; blocked:=true; END; IF NOT blocked THEN RAISE EXCEPTION 'TEST_POSTGRES_PARENT_CASCADE'; END IF;
 UPDATE public.medicamentos SET estoque_quantidade=8 WHERE id='30000000-0000-4000-8000-000000000003'; IF NOT FOUND THEN RAISE EXCEPTION 'TEST_POSTGRES_INACTIVE'; END IF;
END $$;
SET LOCAL ROLE service_role;
DO $$ DECLARE blocked boolean; BEGIN
 blocked:=false; BEGIN UPDATE public.medicamentos SET estoque_quantidade=99 WHERE id='30000000-0000-4000-8000-000000000002'; EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE '%MACRO02_COMPATIBLE_WRITER_REQUIRED%' THEN RAISE; END IF; blocked:=true; END; IF NOT blocked THEN RAISE EXCEPTION 'TEST_SERVICE_NOJWT_ACTIVE'; END IF;
 blocked:=false; BEGIN DELETE FROM public.persons WHERE id='10000000-0000-4000-8000-000000000002'; EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE '%MACRO02_PROTECTED_PERSON_HISTORY%' THEN RAISE; END IF; blocked:=true; END; IF NOT blocked THEN RAISE EXCEPTION 'TEST_SERVICE_PARENT_CASCADE'; END IF;
 UPDATE public.medicamentos SET estoque_quantidade=7 WHERE id='30000000-0000-4000-8000-000000000003'; IF NOT FOUND THEN RAISE EXCEPTION 'TEST_SERVICE_INACTIVE'; END IF;
END $$;
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
DO $$ DECLARE blocked boolean; BEGIN
 blocked:=false; BEGIN PERFORM vault_macro02_private.guard_active_for('20000000-0000-4000-8000-000000000003'); EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE '%MACRO02_GUARD_SCOPE%' THEN RAISE; END IF; blocked:=true; END; IF NOT blocked THEN RAISE EXCEPTION 'TEST_GUARD_CROSS_ACCOUNT'; END IF;
 blocked:=false; BEGIN DELETE FROM public.persons WHERE id='10000000-0000-4000-8000-000000000002'; EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE '%MACRO02_PROTECTED_PERSON_HISTORY%' THEN RAISE; END IF; blocked:=true; END; IF NOT blocked THEN RAISE EXCEPTION 'TEST_AUTH_PARENT_CASCADE'; END IF;
END $$;
